/**
 * Lấy thông tin chi tiết của một chữ Kanji
 */
export function getKanjiInfo(kanji: string): KanjiDetail {
  if (KANJI_DICTIONARY[kanji]) {
    return KANJI_DICTIONARY[kanji];
  }

  const hanViet = SINO_VIETNAMESE_MAP[kanji] || 'Đang cập nhật';

  return {
    kanji,
    hanViet,
    meanings: ['Nhấp để tra cứu nghĩa trực tuyến'],
    on: [],
    kun: [],
    examples: [],
  };
}
